import sys, json

# The librarian's TOOL ADAPTER (GH #950): a model's `tool_call` in, a question
# to `./query` on `in_lib` out, and the one answer back as one `tool_result`
# under the call's id. Nothing is parked: the call id IS the question's `op_id`
# (every answer mirrors it), so route and `op_id` find the call again without a
# store row -- and a question whose answer never comes leaves no orphan behind.
#
# Three refusals are answered here and reach no other cell: a name this
# library does not serve (`tool_unknown`), an argument that does not match the
# tool's schema and a call without an id (`bad_request`). Every tool reads, so
# there is no `read_only` refusal and no writer to tell apart.
ME = "tools"
# --8<-- lib-offer
# THE LIBRARY TOOLS, one list, one entry per tool (GH #950). It stands WORD FOR
# WORD in `./schemas` (which hands it to a model's menu) and in `./tools` (which
# checks every call against it before a question leaves), because a code cell
# has no library it could share. The name IS the mapping: `lib_<op>` asks the
# op `<op>` on `in_lib`; no other rule exists.
#
# Every description says the two things a model needs to go on: the address a
# hit carries (`fh-<12 hex>` for a file, `fh-<12 hex>#<anchor>` for an item in
# it), and that `file_read` with that address reads the span -- the library
# finds, the file space reads. There is no writing tool here.
LIMIT = {"type": "integer", "minimum": 1, "maximum": 20,
         "description": "the most hits on one page (20 by default)"}
CURSOR = {"type": "string", "description": "the `next` of the page before"}
DEPTH = {"type": "integer", "minimum": 1, "maximum": 3}


def _obj(props, required):
    return {"type": "object", "properties": props, "required": required,
            "additionalProperties": False}


LIB_OFFER = [
    {"name": "lib_find",
     "description": "Find files of this knowledge space by words -- in their path, the names "
                    "of their functions, classes or sections, their summary line and tags -- "
                    "best first, each with its address `fh-<12 hex>`, path, kind, summary line "
                    "and `why` it matched. `file_read` on that address (or on an item of it, "
                    "`fh-<12 hex>#<anchor>` from `file_outline`) reads the span; `next` is the "
                    "`cursor` of the next page.",
     "parameters": _obj({"q": {"type": "string", "description": "the words to look for"},
                         "kind": {"type": "string", "description": "only files of this kind"},
                         "fmt": {"type": "string",
                                 "description": "only files of this format: `python`, `rust`, `markdown`, `json`, `toml` or `pdf`"},
                         "under": {"type": "string",
                                   "description": "only files under this folder, like `/src`"},
                         "limit": LIMIT, "cursor": CURSOR}, ["q"])},
    {"name": "lib_symbol",
     "description": "Find where a name is defined: a function, class, module or section, "
                    "bare (`load`) or qualified (`pkg.mod:load`), each hit with its address "
                    "`fh-<12 hex>#<anchor>`, the path of its file and its summary line. "
                    "`file_read` with that address reads exactly that span.",
     "parameters": _obj({"name": {"type": "string", "description": "the name to look up"},
                         "limit": LIMIT, "cursor": CURSOR}, ["name"])},
    {"name": "lib_related",
     "description": "What is connected to an address `fh-<12 hex>` or `fh-<12 hex>#<anchor>`: "
                    "its `callers`, its `dependents` (up to `depth` 3), its `deps`, or files "
                    "`similar` by meaning; each hit with its address, path and summary line. "
                    "`file_read` with a hit's address reads its span.",
     "parameters": _obj({"addr": {"type": "string",
                                  "description": "`fh-<12 hex>` or `fh-<12 hex>#<anchor>`"},
                         "how": {"type": "string",
                                 "enum": ["callers", "dependents", "deps", "similar"]},
                         "depth": DEPTH, "limit": LIMIT, "cursor": CURSOR},
                        ["addr", "how"])},
    {"name": "lib_tree",
     "description": "The folders and files under a folder `under` (`/` by default), `depth` "
                    "levels deep (1 to 3), ordered by path, each file with its address "
                    "`fh-<12 hex>`; `file_read` on that address (or on an item of it, "
                    "`fh-<12 hex>#<anchor>` from `file_outline`) reads the span; `next` is the "
                    "`cursor` of the next page.",
     "parameters": _obj({"under": {"type": "string", "description": "a folder, `/` by default"},
                         "depth": DEPTH, "limit": LIMIT, "cursor": CURSOR}, [])},
]
# --8<-- end lib-offer

TYPES = {"string": (str,), "integer": (int,), "number": (int, float),
         "boolean": (bool,), "array": (list,), "object": (dict,)}


def op_of(name):
    """The op a tool name asks, or None for a name this library does not
    serve."""
    if not isinstance(name, str) or not name.startswith("lib_"):
        return None
    if name not in [t["name"] for t in LIB_OFFER]:
        return None
    return name[len("lib_"):]


def type_ok(v, t):
    if isinstance(t, list):
        return any(type_ok(v, x) for x in t)
    want = TYPES.get(t)
    if want is None:
        return True
    # A JSON `true` is no number: python counts bool as int, a schema does not.
    if isinstance(v, bool) and t != "boolean":
        return False
    return isinstance(v, want)


def check(schema, v, at="arguments"):
    """The problems of `v` against a JSON Schema of the subset `LIB_OFFER`
    uses (type, enum, minimum, maximum, required, properties,
    additionalProperties, items); [] when it holds. A tool argument is typed
    HERE, before any question leaves -- `./query` checks again, for callers
    that are no model."""
    out = []
    t = schema.get("type")
    if t is not None and not type_ok(v, t):
        return ["%s must be %s" % (at, t if isinstance(t, str) else " or ".join(t))]
    if "enum" in schema and v not in schema["enum"]:
        out.append("%s must be one of %s" % (at, ", ".join(map(str, schema["enum"]))))
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if "minimum" in schema and v < schema["minimum"]:
            out.append("%s must be at least %s" % (at, schema["minimum"]))
        if "maximum" in schema and v > schema["maximum"]:
            out.append("%s must be at most %s" % (at, schema["maximum"]))
    if isinstance(v, dict):
        props = schema.get("properties") or {}
        for k in schema.get("required") or []:
            if k not in v:
                out.append("%s.%s is required" % (at, k))
        for k, x in v.items():
            if k in props:
                out.extend(check(props[k], x, "%s.%s" % (at, k)))
            elif schema.get("additionalProperties") is False:
                out.append("%s.%s is not an argument of this tool" % (at, k))
    if isinstance(v, list) and isinstance(schema.get("items"), dict):
        for i, x in enumerate(v):
            out.extend(check(schema["items"], x, "%s[%d]" % (at, i)))
    return out


def result_text(answer):
    """An answer as the text a model reads: the answer's own fields, the
    correlation (`op_id`, `caller`) and the transport (`messages`, `header`)
    removed. Nothing is cut here: `./query` pages every list."""
    keep = {k: v for k, v in answer.items()
            if k not in ("op_id", "caller", "messages", "header")}
    return json.dumps(keep, ensure_ascii=False, sort_keys=True)


def refusal(op, code, message):
    return {"ok": False, "op": op or "", "error": {"code": code, "message": message}}


def tool_result(call_id, answer):
    head = {"route": "tool_result", "tool_call_id": call_id}
    if answer.get("ok") is False:
        head["error_code"] = str((answer.get("error") or {}).get("code") or "")
    return {"header": head,
            "messages": [{"origin": "tool", "type": "tool_result", "id": call_id,
                          "text": result_text(answer)}]}


# A provider's call ids are unique only within one answer (stubs and local
# servers repeat `call_0`): the question carries the call id under this cell's
# own prefix, and the answer finds the call id again without it.
PREFIX = ME + ":"


def call_of(op_id):
    op_id = str(op_id or "")
    return op_id[len(PREFIX):] if op_id.startswith(PREFIX) else op_id


def translate(name, raw, call_id):
    """One tool call -> the ONE message this cell emits for it: the question,
    or a `tool_result` that refuses it without asking any cell."""
    op = op_of(name)
    if op is None:
        return tool_result(call_id, refusal("", "tool_unknown",
                                            "this library has no tool %r" % (name,)))
    if isinstance(raw, dict):
        args = raw
    else:
        try:
            args = json.loads(raw or "{}")
        except Exception:
            args = None
    if not isinstance(args, dict):
        return tool_result(call_id, refusal(op, "bad_request",
                                            "the arguments are not a JSON object"))
    schema = [t for t in LIB_OFFER if t["name"] == name][0]["parameters"]
    bad = check(schema, args)
    if bad:
        return tool_result(call_id, refusal(op, "bad_request", "; ".join(bad)))
    if not call_id:
        return tool_result(call_id, refusal(op, "bad_request", "the call carries no id"))
    return {"header": {"route": "in_lib", "op": op, "op_id": PREFIX + call_id, "caller": ME},
            "op": op, "args": args, "messages": []}


doc = json.load(sys.stdin)
d = doc.get("body") or {}
h = (doc.get("envelope") or {}).get("header") or {}
hop = h.get("hop") or {}
lane = str(hop.get("route") or "")


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


if lane == "in_tool":
    msgs = d.get("messages") or []
    call = msgs[0] if msgs and isinstance(msgs[0], dict) else {}
    # The id comes from the TURN first and the hop second: the turn is what
    # the round's fan-in waits on.
    call_id = str(call.get("id") or hop.get("tool_call_id") or "")
    name = str(hop.get("tool_name") or "")
    emit([translate(name, call.get("text"), call_id)])

if lane == "answer":
    if str(hop.get("caller") or "") != ME:
        sys.stderr.write("librarian/tools: an answer for %r -- dropped\n"
                         % str(hop.get("caller") or ""))
        emit([])
    call_id = call_of(hop.get("op_id") or d.get("op_id"))
    emit([tool_result(call_id, d)])

sys.stderr.write("librarian/tools: unknown lane %r -- dropped\n" % lane)
emit([])
